export default function events({ events, mailbox }) {
  if (!Array.isArray(events)) throw Error("Invalid Gmail events");
  return {
    records: events.map((e) => {
      if (typeof e.messageId !== "string") throw Error("Missing message ID");
      return { id: e.messageId, mailbox };
    }),
  };
}

