export default function next({ records, previous }) {
  const index = (previous?.index ?? -1) + 1;
  return {
    state: { index },
    more: index < records.length,
    id: records[index]?.id ?? "pending",
    mailbox: records[index]?.mailbox ?? "A",
  };
}

