export default function message({ from, body }) {
  if (typeof from !== "string" || typeof body !== "string" || !body.trim())
    throw Error("Email sender or text missing");
  const email = (from.match(/<([^<>]+)>/)?.[1] ?? from).trim();
  if (!/^[^\s@<>]+@[^\s@<>]+\.[^\s@<>]+$/.test(email)) throw Error("Invalid sender address");
  return { email, body };
}

