export default function match({ items }) {
  if (!Array.isArray(items)) throw Error("Invalid person search");
  if (!items.length) return { found: false, id: 1 };
  const id = items[0]?.item?.id;
  if (!Number.isInteger(id) || id < 1) throw Error("Invalid person ID");
  return { found: true, id };
}

