export default function campaign({ person, fieldKey, trueOption }) {
  if (
    !person ||
    typeof person.name !== "string" ||
    !person.name.trim() ||
    fieldKey === "YOUR_CAMPAIGN_FIELD_KEY" ||
    trueOption === "YOUR_TRUE_OPTION_ID"
  )
    throw Error("Configure campaign field and true option");
  const raw = person.custom_fields?.[fieldKey];
  return { active: raw != null && String(raw) === trueOption, title: person.name + " Deal" };
}

