export default async function create({ title, personId }, context) {
  if (typeof title !== "string" || !title || !Number.isInteger(personId) || personId < 1)
    throw Error("Invalid deal");
  const result = await context.actions.call("pipedrive.create_deal", { title, personId });
  if (!result?.deal || !Number.isInteger(result.deal.id))
    throw Error("Deal creation was not confirmed");
  return { created: true };
}
